import { motion, useReducedMotion } from "framer-motion";
import { useState } from "react";

import { AiSeal } from "./AiSeal";

export type CutoutName =
  | "learn-backpack-scale"
  | "learn-bouncing-ball"
  | "learn-balloon"
  | "learn-balloon-popped"
  | "learn-dosimeter"
  | "learn-thermometer"
  | "learn-sundial"
  | "learn-tilt-plank"
  | "learn-bean-piles"
  | "learn-magnifier-hex"
  | "learn-rover"
  | "learn-drone";

interface LearnCutoutProps {
  name: CutoutName;
  className?: string;
}

/**
 * A cardboard object generated by GPT that illustrates an experiment (never a data source).
 * Until the file exists it renders nothing, so the lesson never shows a broken image.
 */
export function LearnCutout({ name, className = "h-24 w-24" }: LearnCutoutProps) {
  const reduceMotion = useReducedMotion();
  const [missing, setMissing] = useState(false);
  if (missing) return null;
  return (
    <motion.span
      key={name}
      className={`relative inline-block shrink-0 ${className}`}
      initial={reduceMotion ? false : { opacity: 0, rotate: -6, y: 8 }}
      animate={{ opacity: 1, rotate: 0, y: 0 }}
      transition={{ type: "spring", stiffness: 180, damping: 14 }}
    >
      <img
        src={`/img/learn/${name}.webp`}
        alt=""
        width={512}
        height={512}
        decoding="async"
        onError={() => setMissing(true)}
        className="h-full w-full select-none object-contain drop-shadow-ckepi-logo"
      />
      <AiSeal className="absolute bottom-0 right-0" />
    </motion.span>
  );
}
